<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import NxAlert from'../../components/ui/NxAlert.vue';import NxBadge from'../../components/ui/NxBadge.vue';import NxButton from'../../components/ui/NxButton.vue';import NxCard from'../../components/ui/NxCard.vue';import NxPageHeader from'../../components/ui/NxPageHeader.vue';import NxTableShell from'../../components/ui/NxTableShell.vue';import{get,post,type Row}from'../technicians/api';
const settings=ref<Row>({}),original=ref<Row>({}),transactions=ref<Row[]>([]),loading=ref(false),saving=ref(false),error=ref(''),notice=ref(''),secret=ref(''),webhook=ref('');const inputClass='min-h-11 w-full rounded-md border border-[var(--nx-border)] bg-[var(--nx-surface)] px-3 text-sm text-[var(--nx-text)]';const enabled=computed({get:()=>Number(settings.value.paymongo_enabled)===1,set:v=>settings.value.paymongo_enabled=v?1:0});const dirty=computed(()=>JSON.stringify(settings.value)!==JSON.stringify(original.value)||!!secret.value||!!webhook.value);const money=(v:any,c='PHP')=>new Intl.NumberFormat('en-PH',{style:'currency',currency:c||'PHP'}).format(Number(v||0));const fmt=(v:any)=>v?new Date(String(v).replace(' ','T')).toLocaleString('en-PH'):'—';const tone=(v:any):'success'|'danger'|'warning'|'neutral'=>['PAID','SUCCEEDED','SUCCESS','COMPLETED'].includes(String(v).toUpperCase())?'success':['FAILED','EXPIRED','CANCELLED'].includes(String(v).toUpperCase())?'danger':['PENDING','PROCESSING'].includes(String(v).toUpperCase())?'warning':'neutral';
async function load(show=false){loading.value=true;error.value='';notice.value='';try{const[s,t]=await Promise.all([get<Row>('/api/v1/payment-gateway/settings'),get<any>('/api/v1/payment-gateway/transactions')]);settings.value={...s};original.value={...s};transactions.value=Array.isArray(t)?t:Array.isArray(t?.items)?t.items:[];secret.value=webhook.value='';if(show)notice.value='Gateway settings and transactions refreshed.';}catch(e){error.value=e instanceof Error?e.message:'Unable to load payment gateway.';}finally{loading.value=false;}}async function save(){saving.value=true;error.value='';try{const payload:Row={paymongo_enabled:enabled.value?1:0,paymongo_mode:settings.value.paymongo_mode||'test',paymongo_public_key:settings.value.paymongo_public_key||''};if(secret.value)payload.paymongo_secret_key=secret.value;if(webhook.value)payload.paymongo_webhook_secret=webhook.value;const s=await post<Row>('/api/v1/payment-gateway/settings/save',payload);settings.value={...s};original.value={...s};secret.value=webhook.value='';notice.value='Payment gateway settings saved.';}catch(e){error.value=e instanceof Error?e.message:'Unable to save gateway settings.';}finally{saving.value=false;}}function discard(){settings.value={...original.value};secret.value=webhook.value='';}
onMounted(()=>void load());
</script>
<template><div class="space-y-4 overflow-x-hidden pb-8 text-[var(--nx-text)]"><NxPageHeader eyebrow="Online collections" title="Payment Gateway" description="Configure PayMongo checkout credentials and monitor online payment transactions."><template #actions><NxButton variant="secondary" :disabled="loading||saving" @click="load(true)">{{loading?'Refreshing…':'Refresh'}}</NxButton><NxButton :disabled="loading||saving||!dirty" @click="save">{{saving?'Saving…':'Save Settings'}}</NxButton></template></NxPageHeader><NxAlert v-if="error||notice" :tone="error?'danger':'success'">{{error||notice}}</NxAlert><div v-if="dirty" class="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-amber-400/40 bg-amber-400/10 px-4 py-3 text-sm"><span><b>Unsaved gateway changes</b> — checkout behavior is unchanged until saved.</span><NxButton variant="secondary" @click="discard">Discard</NxButton></div><div class="grid gap-4 xl:grid-cols-[minmax(320px,.8fr)_minmax(0,1.5fr)]"><NxCard><p class="text-base font-bold">PayMongo configuration</p><p class="mt-1 text-sm text-[var(--nx-text-muted)]">Credentials remain hidden after they are stored.</p><div class="mt-5 space-y-4"><div class="flex items-center justify-between rounded-xl border border-[var(--nx-border)] bg-[var(--nx-surface-muted)] p-4"><div><b>Enable PayMongo</b><p class="text-xs text-[var(--nx-text-muted)]">Allow subscriber checkout.</p></div><button type="button" role="switch" :aria-checked="enabled" class="relative h-7 w-12 rounded-full transition" :class="enabled?'bg-[var(--nx-primary)]':'bg-[var(--nx-border)]'" @click="enabled=!enabled"><span class="absolute top-1 size-5 rounded-full bg-white shadow transition-all" :class="enabled?'left-6':'left-1'"></span></button></div><label class="grid gap-1.5 text-sm font-semibold">Mode<select v-model="settings.paymongo_mode" :class="inputClass"><option value="test">TEST</option><option value="live">LIVE</option></select></label><NxAlert v-if="settings.paymongo_mode==='live'" tone="warning">Live mode can create real financial transactions. Confirm credentials before saving.</NxAlert><label class="grid gap-1.5 text-sm font-semibold">Public Key<input v-model="settings.paymongo_public_key" autocomplete="off" :class="inputClass"></label><label class="grid gap-1.5 text-sm font-semibold">Secret Key<input v-model="secret" type="password" autocomplete="new-password" :placeholder="settings.paymongo_secret_key_configured?'Configured — enter only to replace':'Enter secret key'" :class="inputClass"></label><label class="grid gap-1.5 text-sm font-semibold">Webhook Secret<input v-model="webhook" type="password" autocomplete="new-password" :placeholder="settings.paymongo_webhook_secret_configured?'Configured — enter only to replace':'Enter webhook secret'" :class="inputClass"><small class="font-normal text-[var(--nx-text-muted)]">Used to validate PayMongo callbacks.</small></label></div></NxCard><NxCard><div class="mb-4 flex items-center justify-between"><div><p class="text-base font-bold">Gateway transactions</p><p class="text-sm text-[var(--nx-text-muted)]">{{transactions.length}} records</p></div><NxBadge :tone="enabled?'success':'neutral'">{{enabled?'ENABLED':'DISABLED'}}</NxBadge></div><NxTableShell min-width="920px"><thead class="bg-[var(--nx-surface-muted)] text-xs uppercase"><tr><th class="px-4 py-3">Reference</th><th class="px-4 py-3">Invoice</th><th class="px-4 py-3">Subscriber</th><th class="px-4 py-3 text-right">Amount</th><th class="px-4 py-3">Status</th><th class="px-4 py-3">Created</th></tr></thead><tbody><tr v-if="!transactions.length"><td colspan="6" class="p-12 text-center text-[var(--nx-text-muted)]">No payment gateway transactions found.</td></tr><tr v-for="r in transactions" :key="r.id"><td class="px-4 py-3 font-mono text-xs">{{r.gateway_reference||'—'}}</td><td class="px-4 py-3">{{r.invoice_no||'#'+(r.invoice_id||'—')}}</td><td class="px-4 py-3">{{r.subscriber_name||'—'}}<small class="block text-[var(--nx-text-muted)]">{{r.account_number||''}}</small></td><td class="px-4 py-3 text-right font-semibold">{{money(r.amount,r.currency)}}</td><td class="px-4 py-3"><NxBadge :tone="tone(r.gateway_status)">{{r.gateway_status||'PENDING'}}</NxBadge></td><td class="whitespace-nowrap px-4 py-3">{{fmt(r.created_at)}}</td></tr></tbody></NxTableShell></NxCard></div></div></template>
<style scoped>:global([data-nx-next-root="payment-gateway"]){max-width:100%;overflow-x:hidden}</style>
